  ('stage_5', 'stage', 4::bigint, '{"id":"stage_5","order":4,"key":"Căn bản","emoji":"🎋","color":"#d9805f","whiteText":false,"title":"HSK3 3.0","badge":"Sơ cấp","desc":"Hoàn thiện sơ cấp: đọc đoạn văn ngắn, kể chuyện và diễn đạt ý kiến đơn giản.","chips":["Bài giảng","Từ vựng","Luyện viết","Nghe hiểu","Ngữ pháp","Thi HSK"],"keyword":"HSK3","sections":[],"info":[["Số từ vựng","≈ + 973 từ theo Đại cương HSK mới"],["Số điểm ngữ pháp","40 điểm ngữ pháp trọng tâm"],["Giáo trình","Chuẩn HSK3 3.0"]],"lessons":[["我们去机场接你们","Anh chị sẽ đến sân bay đón các em"],["你们想吃什么就点什么","Các em muốn ăn món gì thì gọi món đó"],["这个小区挺好的","Khu dân cư này khá tốt"],["这家宾馆跟别的都不一样","Khách sạn này không giống như những khách sạn khác"],["这样的照片才好看","Những bức ảnh như thế này mới đẹp"],["高铁上还可以点外卖","Trên tàu cao tốc vẫn có thể đặt đồ ăn giao tận nơi"],["那条裙子比短裤更好看","Chiếc váy đó đẹp hơn quần soóc"],["今天我出院了","Hôm nay tôi xuất viện rồi"],["打不好没关系","Chơi không tốt cũng không sao"],["你明天再把书给我","Ngày mai em trả lại sách cho cô nhé"],["看来我没办法解决这个问题","Xem ra em không thể giải quyết vấn đề này"],["这个季节天气变化很快","Thời tiết thay đổi rất nhanh vào mùa này"],["我的新邻居来自英国","Hàng xóm mới của tôi đến từ Vương quốc Anh"],["这本书被别人借走了","Quyển sách này đã bị người khác mượn rồi"],["我是半个南京人","Em cũng là một nửa người Nam Kinh"],["我听说有的熊猫出国了","Con nghe nói có một số con gấu trúc đã ra nước ngoài"],["我要多向认真的人学习","Mình sẽ học hỏi từ những người cẩn thận"],["我学会了包饺子","Cháu đã học được cách gói sủi cảo"]],"ribbon":"新HSK教程 3 · LỘ TRÌNH GIẢNG DẠY — KHOÁ HSK3 (3.0)","ribbonColor":"#14213d","affKey":"giaotrinh3","cover":"assets/cover-stage-4.jpg","boxes":[]}'::jsonb),
  ('stage_6', 'stage', 5::bigint, '{"id":"stage_6","order":5,"key":"Lên tay","emoji":"🔥","color":"#4fb3a9","whiteText":false,"title":"HSK4 3.0","badge":"Trung cấp","desc":"Giao tiếp tự tin hơn: mở rộng từ vựng, câu phức và đọc hiểu đoạn văn độ dài trung bình.","chips":["Bài giảng","Từ vựng","Luyện viết","Nghe hiểu","Ngữ pháp","Thi HSK"],"keyword":"HSK4","sections":[],"info":[],"lessons":[],"ribbon":"","ribbonColor":"","affKey":"","cover":"","boxes":[]}'::jsonb),
  ('stage_7', 'stage', 6::bigint, '{"id":"stage_7","order":6,"key":"Thành thạo","emoji":"⚡","color":"#e6b34a","whiteText":false,"title":"HSK5 3.0","badge":"Trung cấp","desc":"Đọc báo, xem video và viết đoạn văn mạch lạc; nắm vững ngữ pháp trung - cao cấp.","chips":["Bài giảng","Từ vựng","Luyện viết","Nghe hiểu","Ngữ pháp","Thi HSK"],"keyword":"HSK5","sections":[],"info":[],"lessons":[],"ribbon":"","ribbonColor":"","affKey":"","cover":"","boxes":[]}'::jsonb),
  ('stage_8', 'stage', 7::bigint, '{"id":"stage_8","order":7,"key":"Cao thủ","emoji":"🐉","color":"#b86fa3","whiteText":false,"title":"HSK6 3.0","badge":"Trung cấp","desc":"Hiểu văn bản dài, diễn đạt trôi chảy và luyện đề theo cấu trúc bài thi HSK 6.","chips":["Bài giảng","Từ vựng","Luyện viết","Nghe hiểu","Ngữ pháp","Thi HSK"],"keyword":"HSK6","sections":[],"info":[],"lessons":[],"ribbon":"","ribbonColor":"","affKey":"","cover":"","boxes":[]}'::jsonb),
  ('stage_9', 'stage', 8::bigint, '{"id":"stage_9","order":8,"key":"Bậc thầy","emoji":"👑","color":"#c0392b","whiteText":true,"title":"HSK7–9 3.0","badge":"Cao cấp","desc":"Cao cấp: văn bản học thuật, chuyên ngành và chiến lược thi thật.","chips":["Bài giảng","Từ vựng","Luyện viết","Nghe hiểu","Ngữ pháp","Thi HSK"],"keyword":"HSK","sections":[],"info":[],"lessons":[],"ribbon":"","ribbonColor":"","affKey":"","cover":"","boxes":[]}'::jsonb),
  ('settings', 'settings', 0::bigint, '{"bank":{"name":"MB Bank","number":"0551404022004","owner":"MAI THANH HUYEN","qr":"assets/qr-bank.jpg"},"affiliate":{"giaotrinh":"","giaotrinh2":"","giaotrinh3":"","but":"","vo":""},"tools":[{"k":"giaotrinh","n":"GIÁO TRÌNH","c":"#d9805f","img":"assets/tool-giaotrinh.jpg","t":"Giáo trình New HSK 1, 2, 3","d":"Bộ giáo trình người mới cầm lên là học được ngay, đi từ chào hỏi đến hội thoại cơ bản."},{"k":"but","n":"Bút viết","c":"#d4709f","img":"assets/tool-but.jpg","t":"Bút gel bấm nhiều màu","d":"Nét chữ Hán gọn, đều. Dùng bút đỏ để chấm lỗi và đánh dấu từ mới."},{"k":"vo","n":"Vở ô ly","c":"#4fa898","img":"assets/tool-vo.jpg","t":"Vở luyện nét cơ bản","d":"Tập từng nét, từng bộ thủ trong ô vuông chuẩn, viết đẹp ngay từ đầu."}],"apps":[{"n":"App dịch Hanzii","c":"#3b82d6","h":"<div class=\"ap-card\"><img class=\"ap-img\" src=\"assets/app-0.jpg\" alt=\"Hanzii Dict trên App Store\"><div><b>Từ điển Trung Việt – Hanzii Dict</b><p>Ứng dụng tra từ Trung Việt cho người học. Theo ảnh chụp App Store: 4,7 sao (8,7K lượt đánh giá), xếp #16 mục Giáo dục.</p><a class=\"lnk\" href=\"https://hanzii.net/?hl=vi\" target=\"_blank\" rel=\"noopener\">Mở hanzii.net ›</a></div></div>\n<h5>Hướng dẫn dùng Hanzii</h5><ol class=\"gl\">\n<li><b>Tra từ ở tab “Từ vựng”.</b> Hanzii cho bạn Pinyin và nghĩa, loại từ, từ trái nghĩa và cận nghĩa, ví dụ, lượng từ...<img src=\"assets/app-1.jpg\" alt=\"Giao diện tab Từ vựng\"></li>\n<li><b>Muốn tra bộ thủ, bấm tab “Hán tự”.</b> Bạn thấy âm Hán Việt, bộ, số nét, thứ tự nét, độ phổ biến và dòng “Bộ thành phần”.<img src=\"assets/app-2.jpg\" alt=\"Tab Hán tự\"></li>\n<li><b>Kéo xuống một chút</b> để xem các từ ghép được tạo từ Hán tự đó.<img src=\"assets/app-3.jpg\" alt=\"Từ ghép\"></li>\n<li><b>Còn nhiều mục khác</b> như “Ví dụ”, “Ngữ pháp”... bạn tự khám phá nhé!</li></ol>\n<div class=\"ap-note\"><b>Tool bổ trợ: HanziCraft</b> (hanzicraft.com): phân tích các ký tự của chữ, phân tích bộ thủ và nêu rõ ý nghĩa, cho biết mức độ thông dụng, gợi ý từ ghép đi cùng và độ phổ biến của chúng.</div>"},{"n":"Học cùng ChatGPT","c":"#0f9b78","h":"<p>Mở ChatGPT và dán từng prompt dưới đây. Mỗi prompt dùng cho một ô chat riêng.</p><details class=\"dd\" open><summary>1. Học từ vựng và ngữ pháp: 4 prompt</summary><div><div class=\"pm\"><b>Prompt 1: Phân tích chữ Hán và cách ghi nhớ</b><span>Gõ trước 5-6 chữ Hán rồi dán prompt bên dưới. Nên soạn trong Word rồi copy sang ChatGPT; list nhiều quá ChatGPT dễ bị lag. Kết quả mẫu là một bảng có cột cách nhớ cho từng từ như 学校, 电话, 朋友, 爱好.</span><pre class=\"pt\">Phân tích các chữ Hán trên + Cung cấp một phương pháp để ghi nhớ chúng một cách dễ dàng. Trình bày dưới dạng bảng với các cột theo thứ tự sau: [Từ vựng] - [Ý nghĩa của từ] - [Từ đầu tiên (Ở cột này bạn phân tích chữ Hán thứ nhất và phương pháp để nhớ từ này)] - [Từ thứ hai (Tương tự)] - [Từ thứ ba (Tương tự)] [(Trong trường hợp từ có 2 ký tự trở lên)] - [Phương pháp ghi nhớ]. Lưu ý: Thêm Pinyin cho tất cả các ký tự Hán trong bảng. Vui lòng trả lời một cách có cấu trúc để tăng cường tính dễ đọc.</pre><button type=\"button\" class=\"cp\" data-copy=\"p1\">Sao chép prompt</button></div><div class=\"pm\"><b>Prompt 2: Kiểm tra ngữ pháp cho câu/đoạn văn</b><span>Gõ câu hoặc đoạn văn cần kiểm tra, rồi dán:</span><pre class=\"pt\">Dịch và kiểm tra ngữ pháp của câu/đoạn văn trên.</pre><button type=\"button\" class=\"cp\" data-copy=\"p2\">Sao chép prompt</button></div><div class=\"pm\"><b>Prompt 3: Phân tích câu (dùng cho bài tập luyện dịch)</b><span>Gõ câu cần dịch và phân tích, rồi dán:</span><pre class=\"pt\">Dịch câu trên một cách dễ hiểu, giải thích ý nghĩa. Phân tích các yếu tố: Từ vựng – Ngữ pháp.</pre><button type=\"button\" class=\"cp\" data-copy=\"p3\">Sao chép prompt</button></div><div class=\"pm\"><b>Prompt 4: Tự động tạo ví dụ theo từ vựng</b><span>Gõ 5-6 từ muốn xem ví dụ, rồi dán (đổi HSK 2 theo trình độ của bạn):</span><pre class=\"pt\">Từ các từ vựng phía trên, hãy tạo cho mình các ví dụ tương ứng, rõ ràng, phù hợp với trình độ HSK 2 (Phần này tùy chọn theo trình độ hiện tại của bạn). Trình bày theo bảng: Từ vựng - Phiên âm - Ví dụ.</pre><button type=\"button\" class=\"cp\" data-copy=\"p4\">Sao chép prompt</button></div></div></details><details class=\"dd\"><summary>2. Prompt 1 phân tích bộ thủ bị sai? Cách sửa</summary><div><ul class=\"ul2\"><li>Hiện tại ChatGPT có thể phân tích bộ thủ sai, nên đừng tin hoàn toàn Prompt 1 ở phần bộ thủ.</li><li>Bước 1: tra chữ Hán ở hanzicraft.com để xem chữ được cấu tạo từ các bộ thủ nào.</li><li>Bước 2: copy thông tin ở dòng “Radical”, rồi dán vào prompt sau:</li></ul><pre class=\"pt\">Chữ [Chữ các bạn cần phân tích] được cấu thành từ các bộ thủ sau [thông tin copy từ dòng Radical]. Hãy cung cấp cách ghi nhớ của từ này với 1 câu duy nhất, ngắn gọn, dễ hiểu.</pre><button type=\"button\" class=\"cp\" data-copy=\"fix\">Sao chép prompt</button></div></details><details class=\"dd\"><summary>3. Luyện nói cùng ChatGPT</summary><div><b>10 chủ đề luyện nói</b><ol class=\"ul2\"><li>自我介绍 · Zìwǒ jièshào · Giới thiệu bản thân</li><li>工作和学习 · Gōngzuò hé xuéxí · Công việc và học tập</li><li>我的家庭 · Wǒ de jiātíng · Gia đình của tôi</li><li>我的朋友 · Wǒ de péngyǒu · Bạn của tôi</li><li>我喜欢做什么？ · Wǒ xǐhuān zuò shénme? · Tôi thích làm gì</li><li>我周末喜欢做什么？ · Wǒ zhōumò xǐhuān zuò shénme? · Cuối tuần tôi thích làm gì</li><li>我的一天 · Wǒ de yītiān · Một ngày của tôi</li><li>我怎么去上班/上学？ · Wǒ zěnme qù shàngbān/shàngxué? · Tôi đi làm/đi học bằng cách nào</li><li>买东西 · mǎi dōngxī · Mua sắm</li><li>天气 · Tiānqì · Thời tiết</li></ol><p>Mỗi chủ đề có thể mở rộng và luyện nhiều lần để nói sâu, nói dài hơn khi vốn từ và ngữ pháp tăng lên.</p><b>Câu lệnh cần nhớ khi nói chuyện</b><table class=\"tbl\"><tr><td>Bạn nói chậm một chút</td><td>请说慢一点</td><td>Qǐng shuō màn yìdiǎn</td></tr><tr><td>Tôi nghe không hiểu</td><td>我听不懂</td><td>Wǒ tīng bù dǒng</td></tr><tr><td>Bạn nói đơn giản hơn được không?</td><td>你可以说得简单一点吗？</td><td>Nǐ kěyǐ shuō de jiǎndān yìdiǎn ma?</td></tr><tr><td>Bạn nói lại một lần nữa được không?</td><td>你可以再说一遍吗？</td><td>Nǐ kěyǐ zài shuō yī biàn ma?</td></tr><tr><td>Để tôi suy nghĩ một chút</td><td>让我想一下</td><td>Ràng wǒ xiǎng yīxià</td></tr><tr><td>Tôi có nói sai gì không?</td><td>我有说错什么吗？</td><td>Wǒ yǒu shuō cuò shénme ma?</td></tr></table><p><b>Câu kết thúc:</b> 今天就到这里，谢谢你的帮助，明天我们再继续练习。 (Hôm nay kết thúc tại đây, cảm ơn bạn đã giúp tôi, ngày mai chúng ta lại tiếp tục luyện tập.)</p></div></details><details class=\"dd\"><summary>4. Năm lưu ý khi dùng ChatGPT</summary><div><ol class=\"ul2\"><li><b>Đừng phụ thuộc quá vào AI.</b> Chỉ dùng để hỗ trợ, nếu quá phụ thuộc bạn có thể bị công cụ thay thế ở nhiều lĩnh vực.</li><li><b>Kết quả khác mẫu?</b> Chụp màn hình kết quả mẫu, gửi cho ChatGPT và yêu cầu trả lời theo dạng đó.</li><li><b>Mỗi prompt một ô chat riêng.</b> Không trộn các prompt khác nhau trong cùng một ô chat.</li><li><b>Mỗi prompt chỉ dùng một ô chat cho ngôn ngữ bạn học.</b> Dùng nhiều lần, ChatGPT sẽ hiểu bạn hơn. Đặt tên ô chat (ví dụ “Lấy ví dụ - Tiếng Trung”) để dễ tìm lại.</li><li><b>Quan trọng:</b> đừng nói lời thô tục với AI, nó sẽ “giận” và trả lời kém đi.</li></ol></div></details>"},{"n":"Luyện nói cùng Doubao AI","c":"#e8643c","h":"<div class=\"ap-card\"><div><b>Doubao (豆包)</b><p>Trợ lý AI của ByteDance (công ty của TikTok), dùng miễn phí, nói tiếng Trung rất tự nhiên. Rất hợp để luyện nghe và nói.</p><a class=\"lnk\" href=\"https://www.doubao.com\" target=\"_blank\" rel=\"noopener\">Mở doubao.com ›</a></div></div><h5>Hướng dẫn luyện nói với Doubao</h5><ol class=\"gl\"><li><b>Tải app:</b> tìm “豆包” (Doubao) trên App Store hoặc Google Play, hoặc dùng web doubao.com. Một số nguồn ghi bản quốc tế có tên Cici; hãy kiểm tra nhà phát triển là ByteDance. Giao diện chủ yếu là tiếng Trung nên mở app bằng Hanzii bên cạnh cho dễ.</li><li><b>Đăng ký / đăng nhập</b> rồi vào ô chat.</li><li><b>Dùng chức năng gọi thoại (电话 / voice call) trong app điện thoại.</b> Chat thoại thời gian thực chỉ có trên app di động, cảm giác như nói chuyện với người thật nên bạn phải phản xạ nhanh.</li><li><b>Nhập vai tình huống đời thường:</b> gọi món, hỏi đường, giới thiệu bản thân. Bạn có thể chọn các chủ đề trong danh sách 10 chủ đề ở mục ChatGPT.</li><li><b>Nhờ AI sửa lỗi:</b> bảo nó nói cho bạn biết bạn đúng hay sai và sửa thế nào. Nếu nghe không kịp, nói “请说慢一点”.</li></ol><div class=\"pm\"><b>Câu mở đầu gợi ý (nói hoặc gõ)</b><span>Mình tự soạn: bảo Doubao làm bạn luyện nói trình độ HSK 1, sửa lỗi mỗi khi bạn nói sai, bắt đầu bằng chủ đề giới thiệu bản thân.</span><pre class=\"pt\">你好！请做我的汉语口语陪练。我的水平是 HSK 1，请用简单的句子和我聊天，每次我说错了，请告诉我怎么改。我们先聊“自我介绍”吧。</pre><button type=\"button\" class=\"cp\" data-copy=\"db\">Sao chép prompt</button></div><div class=\"ap-note\"><b>Lưu ý:</b> AI rất tốt để luyện nói, nhưng chưa phải nguồn chắc chắn cho ngữ pháp, pinyin hay chữ Hán, nên đối chiếu với giáo trình hoặc Hanzii. Doubao không có chế độ an toàn trẻ em và dữ liệu lưu ở Trung Quốc, vì vậy đừng chia sẻ thông tin cá nhân.</div>"}],"prompts":{"p1":"Phân tích các chữ Hán trên + Cung cấp một phương pháp để ghi nhớ chúng một cách dễ dàng. Trình bày dưới dạng bảng với các cột theo thứ tự sau: [Từ vựng] - [Ý nghĩa của từ] - [Từ đầu tiên (Ở cột này bạn phân tích chữ Hán thứ nhất và phương pháp để nhớ từ này)] - [Từ thứ hai (Tương tự)] - [Từ thứ ba (Tương tự)] [(Trong trường hợp từ có 2 ký tự trở lên)] - [Phương pháp ghi nhớ]. Lưu ý: Thêm Pinyin cho tất cả các ký tự Hán trong bảng. Vui lòng trả lời một cách có cấu trúc để tăng cường tính dễ đọc.","p2":"Dịch và kiểm tra ngữ pháp của câu/đoạn văn trên.","p3":"Dịch câu trên một cách dễ hiểu, giải thích ý nghĩa. Phân tích các yếu tố: Từ vựng – Ngữ pháp.","p4":"Từ các từ vựng phía trên, hãy tạo cho mình các ví dụ tương ứng, rõ ràng, phù hợp với trình độ HSK 2 (Phần này tùy chọn theo trình độ hiện tại của bạn). Trình bày theo bảng: Từ vựng - Phiên âm - Ví dụ.","fix":"Chữ [Chữ các bạn cần phân tích] được cấu thành từ các bộ thủ sau [thông tin copy từ dòng Radical]. Hãy cung cấp cách ghi nhớ của từ này với 1 câu duy nhất, ngắn gọn, dễ hiểu.","db":"你好！请做我的汉语口语陪练。我的水平是 HSK 1，请用简单的句子和我聊天，每次我说错了，请告诉我怎么改。我们先聊“自我介绍”吧。"},"chipColors":{"Bài giảng":"#7bb8e8","Từ vựng":"#a9c06a","Luyện viết":"#f0a860","Nghe hiểu":"#b79ae0","Ngữ pháp":"#ef8c7e","Thi HSK":"#f2c94c","Bảng Pinyin":"#6fcfc2","Phát âm":"#f19ab9","Bảng bộ thủ thông dụng":"#f0b86e","Luyện đề":"#e6a07a"},"chipEmojis":{"Bài giảng":"🎬","Từ vựng":"📚","Luyện viết":"✍️","Nghe hiểu":"🎧","Ngữ pháp":"🧩","Thi HSK":"🏆","Bảng Pinyin":"🔤","Bảng bộ thủ thông dụng":"🧱","Phát âm":"🗣️","Luyện đề":"📝"},"images":{"logo":"assets/logo.jpg","banner":"assets/banner.jpg","nav1":"assets/nav-1.png","nav2":"assets/nav-2.png","nav3":"assets/nav-3.png","nav4":"assets/nav-4.png"}}'::jsonb)
) as v(id, kind, sort, data)
where not exists (select 1 from public.content);
